# LOL HTML JavaScript API

## Example

```js
'use strict';

const { HTMLRewriter } = require('lol-html'); // path/to/lol-html.js

const chunks = [];
const rewriter = new HTMLRewriter('utf8', (chunk) => {
  chunks.push(chunk);
});

rewriter.on('a[href]', {
  element(el) {
    const href = el
      .getAttribute('href')
      .replace('http:', 'https:');
    el.setAttribute('href', href);

    el.onEndTag((tag)=> {
      console.log(`Tag ended: ${tag.name}`);
    });
  },
});

[
  '<div><a href=',
  'http://example.com>',
  '</a></div>',
].forEach((part) => {
  rewriter.write(Buffer.from(part));
});

rewriter.end();

const output = Buffer.concat(chunks).toString('utf8');
console.log(output);
```

## Building

```bash
rustup update # https://rustup.rs
cargo install wasm-pack

wasm-pack build --target nodejs --release
```

'use strict';

const { HTMLRewriter } = require('lol-html');

const chunks = [];
const rewriter = new HTMLRewriter('utf8', (chunk) => {
  chunks.push(chunk);
});

const endTags = [];
rewriter.on('a[href]', {
  element(el) {
    const href = el
      .getAttribute('href')
      .replace('http:', 'https:');
    el.setAttribute('href', href);
    el.setAttribute("start", 'byte '+el.sourceLocationBytes[0]);

    el.onEndTag((tag) => {
      endTags.push(tag.name);
    });
  },
});

[
  '<div><a href=',
  'http://example.com>',
  '</a></div>',
].forEach((part) => {
  rewriter.write(Buffer.from(part));
});

rewriter.end();

const output = Buffer.concat(chunks).toString('utf8');
if (output != '<div><a href="https://example.com" start="byte 5"></a></div>') {
  throw "fail\ngot: " + output;
}

if (endTags.length != 1 || endTags[0] != 'a') {
  throw "onEndTag fail";
}

use glob::glob;
use std::path::{Path, PathBuf};

const CFLAGS: &[&str] = &[
    "-std=c99",
    "-pthread",
    "-Wcast-qual",
    "-Wwrite-strings",
    "-Wshadow",
    "-Winline",
    "-Wdisabled-optimization",
    "-Wuninitialized",
    "-Wcast-align",
    "-Wcast-align",
    "-Wno-missing-field-initializers",
    "-Wno-address",
];

const SRC_DIR: &str = "src";
const PICOTEST_DIR: &str = "src/deps/picotest";
const INCLUDE_DIR: &str = "../include";

fn glob_c_files<P: AsRef<Path>>(dirname: P) -> Vec<PathBuf> {
    const C_PATTERN: &str = "*.c";
    let cwd = std::env::current_dir().expect("failed to determine working directory");

    glob(
        dirname
            .as_ref()
            .join(C_PATTERN)
            .to_str()
            .expect("Path is not valid unicode."),
    )
    .expect("Failed to read glob pattern")
    .filter_map(Result::ok)
    .inspect(|path| {
        let relative_path = path
            .strip_prefix(&cwd)
            .unwrap_or(path)
            .to_str()
            .expect("non-ascii C source file");
        println!("cargo:rerun-if-changed={relative_path}");
    })
    .collect::<Vec<_>>()
}

fn main() {
    let mut build = cc::Build::new();

    for cflag in CFLAGS {
        build.flag(cflag);
    }

    println!("cargo:rerun-if-changed=../include/lol_html.h");
    println!("cargo:rerun-if-changed=src");
    println!("cargo:rerun-if-changed=build.rs");

    // Collect all the C files from src/deps/picotest and src.
    let mut c_files = glob_c_files(PICOTEST_DIR);

    c_files.append(&mut glob_c_files(SRC_DIR));

    build
        .debug(true)
        .opt_level(0)
        .warnings(true)
        .extra_warnings(true)
        .warnings_into_errors(true)
        .include(INCLUDE_DIR)
        .include(PICOTEST_DIR)
        .files(c_files)
        .compile("lol_html_ctests");
}

//! The test runner for the C API tests.

// ensure it's linked
use lolhtml as _;

unsafe extern "C" {
    fn run_tests() -> i32;
}

fn main() {
    unsafe { std::process::exit(run_tests()) }
}

#ifndef TESTS_H
#define TESTS_H

#include "../../include/lol_html.h"

void test_unsupported_selector();
void test_non_ascii_encoding();
void test_doctype_api();
void test_comment_api();
void test_text_chunk_api();
