    ok(value.data == NULL);

    note("Set attribute");
    int err = lol_html_element_set_attribute(
        element,
        attr2,
        strlen(attr2),
        attr2_value,
        strlen(attr2_value)
    );

    ok(!err);

    note("Remove attribute");
    ok(!lol_html_element_remove_attribute(element, attr1, strlen(attr1)));

    return LOL_HTML_CONTINUE;
